SourceCode.Declaration:
/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field SalesUnit.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesLine, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(SalesLine, SalesUnit), tableStr(UnitOfMeasure), fieldStr(UnitOfMeasure, Symbol))]
class METGUPPricingAttributeSalesLineSalesUnit  extends GUPPricingAttributeSalesLine implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesLine, SalesUnit);
}

    public Set getAllowedValuesWithDescription()
    {
        var ret = new Set(Types::AnyType);
        
        SalesLine       salesLine;
        UnitOfMeasure   unitOfMeasure;

        while select SalesUnit from salesLine
            join unitOfMeasure
            group by Symbol, UnitOfMeasureClass
            where salesLine.SalesUnit == unitOfMeasure.Symbol
        {
            GUPPricingAttributeAllowedValuesObject valueObject =
                new GUPPricingAttributeAllowedValuesObject(unitOfMeasure.Symbol, enum2Str(unitOfMeasure.UnitOfMeasureClass));
            ret.add(valueObject);
        }
        return ret;
    }
